-- users/mark-staff-check
-- Records that this session just passed the authenticator-app check, which unlocks reviewer and
-- admin powers for 12 hours (lib/auth/actor.ts). By token, because confirming the first code
-- replaces the session. Scoped to the session's own user.
--
-- Parameters, with the example values used to render this file:
--   $1 = "example-session-token"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/users.ts. Do not edit by hand.

update "sessions"
set "two_factor_verified_at" = now()
where ("sessions"."token" = $1
  and "sessions"."user_id" = $2)
returning "id";
